def bi(ten: str, cls: str = "") -> Markup:
    """Trả về thẻ <svg class="ic ..."> từ tên icon."""
    noi_dung = _SVG_PATHS.get(ten) or _SVG_PATHS["file-text"]
    lop = f"ic ic--{ten}" + (f" {cls}" if cls else "")
    return Markup(
        f'<svg class="{lop}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        f'stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
        f'{noi_dung}</svg>'
    )
